let puterSDKPromise=null;
function ensurePuterSDK(){
 if(window.puter)return Promise.resolve(window.puter);
 if(puterSDKPromise)return puterSDKPromise;
 puterSDKPromise=new Promise((resolve,reject)=>{
  const script=document.createElement('script');script.src='https://js.puter.com/v2/';script.async=true;
  script.onload=()=>window.puter?resolve(window.puter):reject(new Error('Puter.js loaded but its API was not initialized.'));
  script.onerror=()=>{puterSDKPromise=null;reject(new Error('Could not load Puter.js. Check your internet connection and content restrictions.'))};
  document.head.appendChild(script);
  setTimeout(()=>{if(!window.puter){puterSDKPromise=null;reject(new Error('Puter.js did not finish loading.'))}},20000);
 });
 return puterSDKPromise;
}
async function puterSignedIn(){try{const p=await ensurePuterSDK();return !!p.auth.isSignedIn()}catch{return false}}
async function connectPuterFromClick(button,hint,onConnected){
 const p=window.puter;
 if(!p){if(hint)hint.textContent='Loading Puter sign-in…';try{await ensurePuterSDK();if(hint)hint.textContent='Puter is ready. Select Connect again to open its sign-in window.'}catch(e){if(hint)hint.textContent=e.message||String(e)}return}
 if(button){button.disabled=true;button.textContent='Opening Puter sign-in…'}
 try{if(typeof p.ui?.authenticateWithPuter==='function')await p.ui.authenticateWithPuter();else await p.auth.signIn({request_auth:true});const user=await p.auth.getUser().catch(()=>null);const label=user?.username||user?.email||user?.name||'Puter account';if(hint)hint.textContent='Connected to '+label+'.';onConnected?.(label)}
 catch(error){if(hint)hint.textContent='Puter sign-in did not finish: '+(error?.msg||error?.message||String(error))}
 finally{
  // Puter resolves its auth promise when sign-in completes, but Tauri's native
  // child webview is independent and must be explicitly closed by the host.
  if(typeof A.closePuterAuthPopups==='function'){
   try{await A.closePuterAuthPopups()}catch(error){console.warn('Could not close Puter sign-in popup:',error)}
  }
  if(button){button.disabled=false;button.textContent='Connect Puter account'}
 }
}
async function puterRequest(args){
 const p=await ensurePuterSDK();
 if(!p.auth.isSignedIn())throw new Error('Connect your Puter account in ClassWire AI settings first.');
 if(args.listModels){let timeout;try{const catalogue=await Promise.race([p.ai.listModels(),new Promise((_,reject)=>{timeout=setTimeout(()=>reject(new Error('Puter model discovery timed out after 25 seconds. Check your connection and refresh the model list.')),25000)})]);const models=(Array.isArray(catalogue)?catalogue:[]).map(item=>typeof item==='string'?item:item?.id).filter(id=>typeof id==='string'&&id.length);return {models:[...new Set(models)].sort()}}finally{clearTimeout(timeout)}}
 const tools=(Array.isArray(args.tools)?args.tools:[]).map(tool=>({type:'function',function:{name:tool.name,description:tool.description||'',parameters:tool.parameters||{type:'object',properties:{}}}}));
 const messages=[{role:'system',content:args.system||'You are ClassWire AI.'},...(args.messages||[])];
 const response=await p.ai.chat(messages,{model:args.model,tools,toolChoice:'auto',normalize:true});
 const message=response?.message||response||{};let content=message.content??response?.content??'';
 if(Array.isArray(content))content=content.map(part=>part?.text||'').filter(Boolean).join('\n');
 const rawCalls=message.tool_calls||message.toolCalls||response?.tool_calls||response?.toolCalls||[];
 const toolCalls=rawCalls.map(call=>{let value=call?.function?.arguments??call?.arguments??{};if(typeof value==='string'){try{value=JSON.parse(value)}catch{value={}}}return {name:call?.function?.name||call?.name,arguments:value}}).filter(call=>typeof call.name==='string');
 return {text:typeof content==='string'?content:'',toolCalls};
}
async function requestAI(args){return args.provider==='puter'?puterRequest(args):A.aiChat(args)}
function clip(v,max){let s;try{s=JSON.stringify(v)}catch{s=String(v)}return s.length>max?s.slice(0,max)+'… [truncated]':s}

