if(POP){document.documentElement.classList.add('aiPopout');ensure();refreshLabel()}else{new MutationObserver(inject).observe(document.body,{childList:true,subtree:true});inject();window.addEventListener('storage',e=>{if(e.key===CTX)refreshLabel()})}
